(() => {
"use strict";
if(window.__NOXVisualIntelligenceLoaded)return;window.__NOXVisualIntelligenceLoaded=true;
const $=id=>document.getElementById(id),esc=v=>String(v??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
const state={repo:"",viewerUrl:"",nodes:[],edges:[],explanation:"",selected:"",busy:false};
function status(s,bad=false){const e=$("visualStatus");if(e){e.textContent=s;e.style.color=bad?"var(--red)":"var(--muted)"}}
function showWorkspace(){const p=$("visualIntelligencePanel");if(p)p.scrollIntoView({behavior:"smooth",block:"start"});document.querySelectorAll(".mobiletabs [data-scroll]").forEach(b=>b.classList.toggle("active",b.dataset.scroll==="visualIntelligencePanel"))}
function parseModel(v){const raw=String(v||"").trim();if(!raw)throw Error("Enter a Hugging Face model URL or repository ID.");let repo=raw;
if(/^https?:\/\//i.test(raw)){let u;try{u=new URL(raw)}catch{throw Error("That URL is not valid.")}if(u.protocol!=="https:"||!["huggingface.co","www.huggingface.co"].includes(u.hostname.toLowerCase()))throw Error("Use a public https://huggingface.co model URL.");let p=u.pathname.split("/").filter(Boolean);if(p[0]==="models")p.shift();if(p.length<1||p.length>2||p.some(x=>!/^[A-Za-z0-9][A-Za-z0-9._-]*$/.test(x)))throw Error("Use a model URL like huggingface.co/Qwen/Qwen3.5-4B, not a tree/blob page.");repo=p.join("/")}
else{repo=raw.replace(/^\/+|\/+$/g,"");if(repo.startsWith("hfviewer.com/"))repo=repo.slice(13);const p=repo.split("/");if(p.length<1||p.length>2||p.some(x=>!/^[A-Za-z0-9][A-Za-z0-9._-]*$/.test(x)))throw Error("Repository ID must look like Qwen/Qwen3.5-4B or gpt2.")}
return repo}
function setModel(v){const r=parseModel(v);state.repo=r;state.viewerUrl="https://hfviewer.com/"+r.split("/").map(encodeURIComponent).join("/");$("visualModelName").textContent=r;$("visualModelLink").href="https://huggingface.co/"+r.split("/").map(encodeURIComponent).join("/");$("visualModelLink").textContent="Open original Hugging Face model";$("visualModelCard").classList.remove("hidden");$("visualModelState").textContent="VALIDATED · GRAPH NOT YET VERIFIED";status("Model ID validated. The official viewer will determine whether a graph is available.");return state.viewerUrl}
function openViewer(){try{const u=setModel($("visualModelInput").value);window.open(u,"_blank","noopener,noreferrer");status("Opening official HF Viewer in a new tab. Return here for your conversation.")}catch(e){status(e.message,true)}}
function localTemplate(topic,kind){const q=topic.toLowerCase();let title,labels,details;
if(/transformer|attention|llm|neural network|neural net|qwen|language model/.test(q)){title="Transformer / language-model flow";labels=["Input text","Tokenization + embeddings","Attention blocks","Feed-forward + residuals","Output probabilities","Next token / answer"];details=["The original prompt enters the model.","Text is split into tokens and converted into numerical vectors with position information.","Attention layers combine information across token positions. Exact variants depend on the model.","Feed-forward layers transform token features; normalization and residual paths help information flow.","The output head converts the final representation into scores over tokens or task outputs.","During generation, decoding chooses a token and repeats. Internals vary by model."]}
else if(/api|request|server|client|backend|frontend|http|sequence/.test(q)||kind==="sequence"){title="Client-to-service request flow";labels=["User / client","NOX frontend","FastAPI endpoint","AI or data service","Response + UI update"];details=["The user submits a question or action.","The frontend validates input and sends an HTTPS request.","The backend validates the request, applies session and permission checks, and calls the handler.","A configured provider or service processes the request and can fail or time out.","The backend returns a result or error; the frontend displays it."]}
else if(/data flow|pipeline|etl|ingest|index|retriev|rag|knowledge/.test(q)||kind==="dataflow"){title="Data-flow pipeline";labels=["Source data","Validate + extract","Chunk / transform","Index / store","Retrieve + cite"];details=["Documents, URLs, or records are the source.","The system checks supported formats and extracts text or fields.","Content is cleaned and split into manageable chunks.","Data is saved in an index or database with source metadata.","A query retrieves relevant records and source links."]}
else if(/timeline|history|chronolog/.test(q)||kind==="timeline"){title="Example timeline";labels=["Define goal","Prepare inputs","Execute","Review results","Iterate"];details=["Set the outcome and success criteria.","Gather inputs, permissions, and dependencies.","Run the main process.","Check results and note gaps.","Improve the next iteration based on evidence."]}
else if(/decision|workflow|process|steps|how to|flow/.test(q)||kind==="flowchart"){title="Process flow";labels=["Start / input","Validate request","Choose path","Perform action","Check result","Finish / retry"];details=["A request starts the process.","Check required information.","Choose a branch based on a condition.","Execute the selected action with safeguards.","Verify the outcome.","Return the result or report an error."]}
else{title="Concept overview";labels=["Question / input","Core idea","Main components","How they connect","Outcome"];details=["Start with the problem or question.","Identify the central concept.","Break the topic into important components.","Show dependencies or communication between components.","Summarize what the system produces."]}
const nodes=labels.map((label,i)=>({id:"n"+i,label,detail:details[i]})),edges=nodes.slice(1).map((n,i)=>({from:nodes[i].id,to:n.id,label:""}));if(["system","network"].includes(kind)&&nodes.length>=5)edges.push({from:"n1",to:"n3",label:"supporting path"});return{title,explanation:"Local conceptual template for “"+topic+"”. This is a learning aid, not a verified diagram of a specific implementation. Select any node to inspect its role.",nodes,edges,source:"local"}}
function normalize(v){if(!v||typeof v!=="object")return null;const nodes=(Array.isArray(v.nodes)?v.nodes:[]).slice(0,12).map((n,i)=>({id:String(n.id||"n"+i).replace(/[^A-Za-z0-9_-]/g,"").slice(0,30)||"n"+i,label:String(n.label||n.name||("Step "+(i+1))).slice(0,70),detail:String(n.detail||n.description||n.explanation||"").slice(0,700)}));const ids=new Set(nodes.map(n=>n.id));if(nodes.length<2)return null;const edges=(Array.isArray(v.edges)?v.edges:[]).slice(0,24).map(e=>({from:String(e.from||e.source||""),to:String(e.to||e.target||""),label:String(e.label||"").slice(0,50)})).filter(e=>ids.has(e.from)&&ids.has(e.to)&&e.from!==e.to);if(!edges.length)for(let i=1;i<nodes.length;i++)edges.push({from:nodes[i-1].id,to:nodes[i].id,label:""});return{title:String(v.title||"Visual explanation").slice(0,100),explanation:String(v.explanation||"").slice(0,5000),nodes,edges,source:"ai"}}
function drawSvg(kind){const ns=state.nodes,es=state.edges;if(!ns.length)return;const wide=kind==="sequence"||kind==="timeline",cols=wide?Math.min(5,ns.length):(["system","network","dataflow"].includes(kind)?3:1),cw=wide?180:(cols===1?560:220),ch=120,gx=wide?22:18,gy=26,rows=Math.ceil(ns.length/cols),w=cols*cw+(cols-1)*gx+40,h=rows*ch+(rows-1)*gy+40,pos=new Map();ns.forEach((n,i)=>{const c=i%cols,r=Math.floor(i/cols);pos.set(n.id,{x:20+c*(cw+gx),y:20+r*(ch+gy),w:cw,h:104})});let svg='<svg class="visual-svg" viewBox="0 0 '+w+" "+h+'" role="img" aria-label="Interactive visual explanation"><defs><marker id="noxVisualArrow" markerWidth="8" markerHeight="8" refX="6" refY="3" orient="auto"><path d="M0,0 L0,6 L6,3 z" fill="#71eaff"/></marker></defs>';
es.forEach(e=>{const a=pos.get(e.from),b=pos.get(e.to);if(!a||!b)return;const x1=a.x+a.w/2,y1=a.y+a.h/2,x2=b.x+b.w/2,y2=b.y+b.h/2;let d;if(Math.abs(y2-y1)>Math.abs(x2-x1)*.6){const sy=y2>y1?a.y+a.h:a.y,ey=y2>b.y?b.y:b.y+b.h,mid=(sy+ey)/2;d="M "+x1+" "+sy+" C "+x1+" "+mid+", "+x2+" "+mid+", "+x2+" "+ey}else{const sx=x2>x1?a.x+a.w:a.x,ex=x2>x1?b.x:b.x+b.w;d="M "+sx+" "+y1+" L "+ex+" "+y2}svg+='<path class="visual-edge" d="'+d+'" marker-end="url(#noxVisualArrow)"/>';if(e.label)svg+='<text class="visual-edge-label" x="'+((x1+x2)/2)+'" y="'+((y1+y2)/2-7)+'">'+esc(e.label)+"</text>"});
ns.forEach((n,i)=>{const p=pos.get(n.id),lim=wide?22:34,label=n.label.length>lim?n.label.slice(0,lim-1)+"…":n.label;svg+='<g class="visual-node'+(n.id===state.selected?" selected":"")+'" data-node-id="'+esc(n.id)+'" tabindex="0" role="button" aria-label="'+esc(n.label)+'"><rect x="'+p.x+'" y="'+p.y+'" width="'+p.w+'" height="'+p.h+'" rx="12"/><text class="visual-node-index" x="'+(p.x+14)+'" y="'+(p.y+23)+'">NODE '+String(i+1).padStart(2,"0")+'</text><text class="visual-node-label" x="'+(p.x+14)+'" y="'+(p.y+49)+'">'+esc(label)+'</text><text class="visual-node-hint" x="'+(p.x+14)+'" y="'+(p.y+74)+'">SELECT TO INSPECT</text></g>'});$("visualDiagram").innerHTML=svg+"</svg>"}
function selectNode(id){const n=state.nodes.find(x=>x.id===id);if(!n)return;state.selected=id;$("visualNodeName").textContent=n.label;$("visualNodeDetailText").textContent=n.detail||"No component-specific detail was provided.";$("visualFollowupContext").textContent="Selected: "+n.label;$("visualDiagram").querySelectorAll(".visual-node").forEach(e=>e.classList.toggle("selected",e.dataset.nodeId===id))}
function renderDiagram(d,kind){state.nodes=d.nodes;state.edges=d.edges;state.explanation=d.explanation||"";state.selected=d.nodes[0]?.id||"";$("visualDiagramTitle").textContent=d.title;$("visualDiagramState").textContent=d.source==="ai"?"AI-GENERATED STRUCTURE":"LOCAL TEMPLATE · CONCEPTUAL";$("visualExplanation").textContent=state.explanation||"Select a node to read its explanation.";$("visualDiagramWrap").classList.remove("hidden");$("visualNodeDetail").classList.remove("hidden");drawSvg(kind);selectNode(state.selected)}
function parseJson(reply){const t=String(reply||"").trim();try{return JSON.parse(t)}catch{}const a=t.indexOf("{"),b=t.lastIndexOf("}");if(a>=0&&b>a){try{return JSON.parse(t.slice(a,b+1))}catch{}}return null}
async function askProvider(message){const session=await fetch("/api/session",{credentials:"same-origin",cache:"no-store"});if(!session.ok)throw Error("Could not establish a private browser session.");const r=await fetch("/api/chat",{method:"POST",credentials:"same-origin",headers:{"Content-Type":"application/json"},body:JSON.stringify({message,language:$("language")?.value||"auto",history:[]})});let d={};try{d=await r.json()}catch{}if(!r.ok)throw Error(d.detail||("AI request failed with HTTP "+r.status));return d}
async function generateVisual(prompt,kind){if(state.busy)return;const topic=String(prompt||"").trim();if(!topic){status("Enter a topic or question first.",true);return}state.busy=true;$("visualGenerateBtn").disabled=true;$("visualGenerateBtn").textContent="Generating…";$("visualDiagramWrap").classList.add("hidden");status("Preparing a visual explanation…");
const request=["You are NOX Visual Intelligence. Respond with ONLY valid JSON, no markdown fences.","Schema: {\"title\":\"short title\",\"explanation\":\"clear explanation in the user's language\",\"nodes\":[{\"id\":\"n1\",\"label\":\"short label\",\"detail\":\"what this component does\"}],\"edges\":[{\"from\":\"n1\",\"to\":\"n2\",\"label\":\"optional\"}]}","Create 3-10 nodes and up to 18 edges. Every edge endpoint must match a node id. Keep labels short, details useful and accurate. Mark unknown implementation details as conceptual or inferred, not verified.","Use language matching the user's prompt or NOX language setting. Diagram type: "+kind+".","Topic/request: "+topic].join("\n");
try{const data=await askProvider(request),parsed=data.mode==="demo"?null:normalize(parseJson(data.reply));if(parsed){if(!parsed.explanation)parsed.explanation=data.reply;renderDiagram(parsed,kind);status("Visual generated by the configured AI provider. Verify implementation-specific claims against documentation.")}else{const d=localTemplate(topic,kind);if(data.mode!=="demo"&&data.reply&&!/I received your message:/i.test(data.reply))d.explanation+="\n\nAI explanation:\n"+data.reply.slice(0,1800);renderDiagram(d,kind);status(data.mode==="demo"?"AI provider is in demo mode. Showing a local conceptual template, not an AI-verified diagram.":"AI did not return valid diagram structure. Showing a local conceptual template.",true)}}catch(e){renderDiagram(localTemplate(topic,kind),kind);status("AI explanation unavailable: "+e.message+" Showing a local conceptual template instead.",true)}finally{state.busy=false;$("visualGenerateBtn").disabled=false;$("visualGenerateBtn").textContent="Generate visual"}}
async function followup(){const q=$("visualFollowup").value.trim();if(!q)return;const n=state.nodes.find(x=>x.id===state.selected),prompt="Answer this follow-up in the selected language. Topic: "+$("visualPrompt").value+"\nDiagram: "+$("visualDiagramTitle").textContent+"\nExplanation: "+state.explanation+"\nSelected component: "+(n?n.label+" — "+n.detail:"none")+"\nQuestion: "+q+"\nDistinguish verified facts from conceptual assumptions.";$("visualFollowupAnswer").textContent="Thinking…";$("visualFollowupAnswer").classList.remove("hidden");try{const d=await askProvider(prompt);$("visualFollowupAnswer").textContent=d.reply||"No answer returned."}catch(e){$("visualFollowupAnswer").textContent="Follow-up unavailable: "+e.message}$("visualFollowup").value=""}
function handleCommand(text){const raw=String(text||"").trim();if(!raw)return false;const intent=/\b(visual(?:ly|ization)?|diagram|flowchart|visual flow|architecture|architectural graph|model architecture|neural network|transformer works|show .*model|show .*flow|explain .*(?:diagram|flow|visually)|graphically|interactive diagram|is ai model ka .*flow|visual mein dikha|visual me dikha|flow samjha)\b/i.test(raw);if(!intent)return false;showWorkspace();const modelLike=/\b(?:hugging\s*face|hfviewer|qwen|llama|mistral|gemma|phi-\d|whisper)\b/i.test(raw),match=raw.match(/https?:\/\/huggingface\.co\/[A-Za-z0-9._-]+(?:\/[A-Za-z0-9._-]+)?|(?<![\w.-])[A-Za-z0-9][A-Za-z0-9._-]*\/[A-Za-z0-9][A-Za-z0-9._-]*/);if(modelLike){if(match){$("visualModelInput").value=match[0];openViewer();$("visualPrompt").value=raw;status("Model request routed to HF Viewer. Its official page will report graph availability.")}else{$("visualPrompt").value=raw;status("Enter the exact Hugging Face repository ID or URL in the model field to open its architecture viewer.")}return true}else{$("visualPrompt").value=raw;const kind=/sequence|api|request|server/i.test(raw)?"sequence":/timeline|chronolog/i.test(raw)?"timeline":/data.?flow|rag|retriev|pipeline/i.test(raw)?"dataflow":/system|software architecture|coding architecture/i.test(raw)?"system":/process|workflow|decision/i.test(raw)?"flowchart":"auto";$("visualType").value=kind;generateVisual(raw,kind)}return true}
window.NOXVisualIntelligence={handleCommand,openModel:openViewer,generate:generateVisual};
$("visualModelForm").addEventListener("submit",e=>{e.preventDefault();openViewer()});$("visualOpenViewer").addEventListener("click",openViewer);
$("visualCopyViewer").addEventListener("click",async()=>{try{const u=setModel($("visualModelInput").value);await navigator.clipboard.writeText(u);status("Viewer URL copied.")}catch(e){status(e.message||"Clipboard access unavailable.",true)}});
$("visualPromptForm").addEventListener("submit",e=>{e.preventDefault();generateVisual($("visualPrompt").value,$("visualType").value)});
$("visualDiagram").addEventListener("click",e=>{const n=e.target.closest("[data-node-id]");if(n)selectNode(n.dataset.nodeId)});$("visualDiagram").addEventListener("keydown",e=>{const n=e.target.closest("[data-node-id]");if(n&&(e.key==="Enter"||e.key===" ")){e.preventDefault();selectNode(n.dataset.nodeId)}});
$("visualFollowupForm").addEventListener("submit",e=>{e.preventDefault();followup()});document.querySelectorAll('[data-scroll="visualIntelligencePanel"]').forEach(b=>b.addEventListener("click",showWorkspace));
})();